import 'package:flutter/material.dart';

class VideoConsultationScreen extends StatelessWidget {
  const VideoConsultationScreen({super.key,required this.doctorName,required this.appointmentAt,required this.mode,required this.joinUrl});
  final String doctorName; final DateTime appointmentAt; final String mode; final String? joinUrl;
  bool get ready=>mode.toLowerCase().contains('video') && joinUrl != null && joinUrl!.trim().isNotEmpty;
  @override Widget build(BuildContext context){final d=appointmentAt;return Scaffold(appBar:AppBar(title:const Text('Video Consultation')),body:ListView(padding:const EdgeInsets.all(20),children:[const Icon(Icons.video_call_outlined,size:72),const SizedBox(height:16),Text(doctorName,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold),textAlign:TextAlign.center),const SizedBox(height:8),Text('${d.day}/${d.month}/${d.year} • ${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}',textAlign:TextAlign.center),const SizedBox(height:24),Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Before you join',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),const SizedBox(height:10),const Text('• Check your camera and microphone\n• Use a stable internet connection\n• Keep your prescription and reports nearby'),const SizedBox(height:12),const Text('For privacy, the consultation opens only through the meeting link supplied by the healthcare backend.')]))),const SizedBox(height:24),FilledButton.icon(onPressed:ready?()=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Open consultation: ${joinUrl!}'))):null,icon:const Icon(Icons.video_camera_front),label:Text(ready?'Join consultation':'Meeting link not available yet')),if(!ready)const Padding(padding:EdgeInsets.only(top:12),child:Text('Your appointment is not ready for video yet. Please return when the provider has issued a meeting link.',textAlign:TextAlign.center))]));}
}
